//! Golden tests from the ACVP-derived OpenSSL EVP data
//! (`evppkey_slh_dsa_keygen.txt`, `evppkey_slh_dsa_siggen.txt`,
//! `evppkey_slh_dsa_sigver.txt`).
//!
//! Covers keygen KATs for all 12 parameter sets, deterministic ACVP
//! signature matches, signature verification accept/reject, and
//! sign/verify round trips.

use super::*;
use alloc::string::String;
use alloc::vec::Vec;

fn hex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn to_hex(b: &[u8]) -> String {
    let mut s = String::with_capacity(b.len() * 2);
    for x in b {
        s.push_str(&alloc::format!("{x:02x}"));
    }
    s
}

fn variant(name: &str) -> SlhDsaVariant {
    SlhDsaVariant::from_name(name).unwrap()
}

