#[test]
fn keygen_kat() {
    for v in KEYGEN_VECS {
        let var = variant(v.variant);
        let seed = hex(v.seed);
        let (pk, sk) = keygen(var, &seed).expect("keygen");
        assert_eq!(
            to_hex(pk.to_bytes()),
            v.pub_key.to_ascii_lowercase(),
            "pub {}",
            v.variant
        );
        assert_eq!(
            to_hex(sk.to_bytes()),
            v.priv_key.to_ascii_lowercase(),
            "priv {}",
            v.variant
        );
    }
}

