fn acvp_siggen_match() {
    for v in SIGGEN_VECS {
        let var = variant(v.variant);
        let sk = SlhDsaPrivateKey::from_bytes(var, &hex(v.sk)).expect("sk");
        let msg = hex(v.msg);
        let ctx = hex(v.ctx);
        let sig = sign(&sk, &msg, &ctx, false).expect("sign");
        assert_eq!(
            to_hex(&sig),
            v.sig.to_ascii_lowercase(),
            "siggen {}",
            v.variant
        );
    }
}

