#[test]
fn acvp_sigver_accept_reject() {
    for v in SIGVER_VECS {
        let var = variant(v.variant);
        let pk = SlhDsaPublicKey::from_bytes(var, &hex(v.pk)).expect("pk");
        let msg = hex(v.msg);
        let ctx = hex(v.ctx);
        let sig = hex(v.sig);
        let ok = verify(&pk, &msg, &ctx, &sig, false).expect("verify");
        if v.reject {
            assert!(!ok, "should reject {}", v.variant);
        } else {
            assert!(ok, "should accept {}", v.variant);
        }
    }
}

// ==================== sign/verify round trip ====================

#[test]
fn sign_verify_roundtrip_all_variants() {
    for v in SlhDsaVariant::all() {
        let var = *v;
        let mut seed = alloc::vec![0u8; 3 * var.params().n];
        for (i, b) in seed.iter_mut().enumerate() {
            *b = (i as u8).wrapping_mul(7).wrapping_add(3);
        }
        let (pk, sk) = keygen(var, &seed).expect("keygen");
        let msg = b"roundtrip message";
        let ctx = b"ctx";
        let sig = sign(&sk, msg, ctx, false).expect("sign");
        assert_eq!(sig.len(), var.signature_len());
        assert!(
            verify(&pk, msg, ctx, &sig, false).expect("verify"),
            "rt {}",
            var.name()
        );
        assert!(
            !verify(&pk, b"roundtrip messagf", ctx, &sig, false).expect("verify"),
            "tamper {}",
            var.name()
        );
    }
}

#[test]
fn prehash_roundtrip() {
    let var = SlhDsaVariant::Sha2_128f;
    let seed = [0x11u8; 48];
    let (pk, sk) = keygen(var, &seed).expect("keygen");
    let msg = b"prehash me";
    let sig = sign(&sk, msg, b"c", true).expect("sign");
    assert!(verify(&pk, msg, b"c", &sig, true).expect("verify"));
    assert!(
        !verify(&pk, msg, b"c", &sig, false).expect("verify"),
        "pure must not accept prehash sig"
    );
}

#[test]
fn key_bytes_roundtrip() {
    let var = SlhDsaVariant::Shake_128s;
    let seed = [0x5au8; 48];
    let (pk, sk) = keygen(var, &seed).expect("keygen");
    let pk2 = SlhDsaPublicKey::from_bytes(var, pk.to_bytes()).expect("pk");
    let sk2 = SlhDsaPrivateKey::from_bytes(var, sk.to_bytes()).expect("sk");
    assert_eq!(pk, pk2);
    assert_eq!(sk, sk2);
    assert!(SlhDsaPublicKey::from_bytes(var, &pk.to_bytes()[..16]).is_err());
    assert!(SlhDsaPrivateKey::from_bytes(var, &sk.to_bytes()[..32]).is_err());
}

#[test]
fn ctx_too_long_errors() {
    let var = SlhDsaVariant::Sha2_128s;
    let seed = [0x2bu8; 48];
    let (pk, sk) = keygen(var, &seed).expect("keygen");
    let long_ctx = alloc::vec![0u8; 256];
    assert!(sign(&sk, b"m", &long_ctx, false).is_err());
    assert!(verify(&pk, b"m", &long_ctx, &[0u8; 7856], false).is_err());
}

#[test]
fn wrong_length_sig_rejected() {
    let var = SlhDsaVariant::Sha2_128s;
    let seed = [0x2cu8; 48];
    let (pk, _sk) = keygen(var, &seed).expect("keygen");
    assert!(!verify(&pk, b"m", b"", &[0u8; 10], false).expect("verify"));
}
